def top_word_per_length(text):
    groups = {}
    for word in text.split():
        groups.setdefault(len(word), []).append(word)
    result = {}
    for length, words in groups.items():
        tally = {}
        for w in words:
            tally[w] = tally.get(w, 0) + 1
        best_count = max(tally.values())
        winners = sorted(w for w, c in tally.items() if c == best_count)
        result[length] = winners[0]
    return result

