def format_fraction_as_mixed(numerator, denominator):
    import math
    whole, rem = divmod(numerator, denominator)
    if rem == 0:
        return str(whole)
    g = math.gcd(rem, denominator)
    rem, denom = rem // g, denominator // g
    if whole == 0:
        return f"{rem}/{denom}"
    return f"{whole} {rem}/{denom}"

def count_specific_weekday_between(date1, date2, weekday):
    def is_leap(year):
        return year % 4 == 0 and (year % 100 != 0 or year % 400 == 0)

    def days_in_month(year, month):
        lengths = [31, 29 if is_leap(year) else 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
        return lengths[month - 1]

    def ordinal(date):
        year, month, day = date
        total = day
        for m in range(1, month):
            total += days_in_month(year, m)
        for y in range(1, year):
            total += 366 if is_leap(y) else 365
        return total

    start = ordinal(date1)
    end = ordinal(date2)
    start_weekday = (start + 5) % 7
    span = end - start + 1
    count, extra = divmod(span, 7)
    for offset in range(extra):
        if (start_weekday + offset) % 7 == weekday:
            count += 1
    return count

