def is_unimodal(lst):
    n = len(lst)
    if n < 3:
        return False
    i = 0
    while i < n - 1 and lst[i] < lst[i + 1]:
        i += 1
    if i == 0 or i == n - 1:
        return False
    while i < n - 1 and lst[i] > lst[i + 1]:
        i += 1
    return i == n - 1

def rank_normalize_scores_avg_tie(scores):
    n = len(scores)
    if n <= 1:
        return [0.0] * n
    ordered = sorted(scores)
    rank_sum = {}
    rank_count = {}
    for pos, val in enumerate(ordered):
        rank_sum[val] = rank_sum.get(val, 0) + pos
        rank_count[val] = rank_count.get(val, 0) + 1
    avg = {val: rank_sum[val] / rank_count[val] for val in rank_sum}
    return [round(avg[v] / (n - 1), 4) for v in scores]

