def double_shift_day_delta(hh, mm, offset_minutes):
    total_minutes = hh * 60 + mm + offset_minutes
    delta_days = total_minutes // 1440
    if delta_days > 0:
        return 'next'
    if delta_days < 0:
        return 'previous'
    return 'same'
